import {escapeText, inlineText, renderText} from './reader.js';
import {tutorSettings} from './tutor.js';
export const esc = escapeText;
export const enc = encodeURIComponent;
const paths = {
  book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4V4Zm16 0h-4a3 3 0 0 0-3 3m0 14a4 4 0 0 1 4-2h3V4',
  grid:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',
  cards:'M6 7h14v13H6zM3 16V4h14',
  bookmark:'M6 3h12v18l-6-4-6 4V3Z',
  settings:'M10 3h4l1 3 3 1 2 3v4l-2 3-3 1-1 3h-4l-1-3-3-1-2-3v-4l2-3 3-1 1-3Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  plus:'M12 5v14M5 12h14', arrow:'M5 12h14m-6-6 6 6-6 6', back:'M19 12H5m6-6-6 6 6 6',
  chevron:'m9 5 7 7-7 7', down:'m5 9 7 7 7-7', search:'M21 21l-6-6m2-5a7 7 0 1 1-14 0 7 7 0 0 1 14 0',
  upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6', download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',
  file:'M5 3h9l5 5v13H5V3Zm9 0v6h5M8 13h8M8 17h6', graph:'M7 12h10M12 7v10M7 5a2 2 0 1 1-4 0 2 2 0 0 1 4 0Zm14 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0ZM7 19a2 2 0 1 1-4 0 2 2 0 0 1 4 0Zm14 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0ZM5 7v10M19 7v10M7 5h10M7 19h10',
  list:'M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1', clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  check:'m5 12 4 4L19 6', close:'m6 6 12 12M6 18 18 6', circle:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
  trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',
  shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6', sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  spark:'m12 3 2 6 7 3-7 2-2 7-2-7-7-2 7-3 2-6Z', target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-4 0a5 5 0 1 1-10 0 5 5 0 0 1 10 0Zm-5 0h.01',
  edit:'m4 16 12-12 4 4L8 20H4v-4Zm10-10 4 4', more:'M5 12h.01M12 12h.01M19 12h.01', lock:'M6 10h12v11H6V10Zm3 0V6a3 3 0 0 1 6 0v4',
  minus:'M5 12h14', fit:'M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6', menu:'M4 6h16M4 12h16M4 18h16',
  refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1', external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',
  help:'M9 8a3 3 0 1 1 5 2c-1 1-2 1-2 4m0 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', leaf:'M5 21V11C5 5 11 2 21 3c-1 10-6 15-13 14m0-2 9-8',
};
export const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.book}"/></svg>`;
export const link = (cid, mid, tab='study') => `#/course/${enc(cid)}${mid ? `/module/${enc(mid)}/${tab}`:''}`;
export const courseLink = c => link(c.id)+(c.status!=='ready'&&c.modules.some(m=>m.package)?'/explore':'');
export const deleteCourseButton = (c,compact=false) => `<button class="${compact?'icon-btn':'btn'} danger" data-action="delete-course" data-course="${esc(c.id)}" aria-label="Delete course ${esc(c.title)}" title="Delete course">${icon('trash')}${compact?'':'Delete course'}</button>`;
export function deleteCourseDialog(c){
  const running=c.job?.state==='running';
  return `<section class="modal" role="dialog" aria-modal="true" aria-labelledby="delete-course-title"><div class="modal-head"><h2 id="delete-course-title">Delete this course?</h2><button class="icon-btn" data-action="close-modal" aria-label="Close deletion dialog">${icon('close')}</button></div><div class="modal-body"><p><strong>${esc(c.title)}</strong> will be removed from your workspace, including its saved lessons and study progress. A recovery copy of the course and its PDFs is saved first.</p>${running?'<p class="coverage-note">Preparation is still running. You can delete this course after it finishes or pauses.</p>':''}<div class="row wrap"><button class="btn" data-action="close-modal">Keep course</button><button class="btn danger" data-action="confirm-delete-course" data-course="${esc(c.id)}" ${running?'disabled':''}>Delete course</button></div></div></section>`;
}
export function deletionReceipt(info){
  return `<aside class="notice deletion-receipt" role="status"><span>Course deleted. A recovery copy is saved on this computer.${info.cleanup_pending?' Some files are still in use; the recovery copy is complete.':''}</span><a class="text-btn" href="${esc(info.recovery_url)}" download>Download recovery copy ${icon('download')}</a><button class="icon-btn" data-action="dismiss-deletion" aria-label="Dismiss deletion notice">${icon('close')}</button></aside>`;
}
export function preparationNotice(c){
  if(!c.modules.length||(c.status==='ready'&&c.job?.state!=='running'))return '';
  const ready=c.modules.filter(m=>m.package).length,running=c.job?.state==='running';
  return `<aside class="notice preparation-notice" role="status"><div><strong>${ready} of ${c.modules.length} modules ready</strong><p>${running?'Preparation continues in the background.':c.job?.state==='paused'?'Preparation is paused. Your ready modules are saved.':'Your saved modules are ready to explore.'} ${esc(c.job?.message||'')}</p></div><a class="btn sm" href="${link(c.id)}/setup">View preparation</a></aside>`;
}
export const labelState = s => ({unseen:'Unseen',weak:'Needs review',learning:'Learning',mastered:'Strong recall'}[s] || 'Unseen');
export const statePill = m => `<span class="pill ${m.state === 'mastered'?'green':m.state === 'learning'?'amber':m.state === 'weak'?'red':''}"><span class="status-dot ${esc(m.state)}"></span>${labelState(m.state)}</span>`;
export const inline = inlineText;
export const rich = renderText;
export function dueCards(courses,cid=null,mid=null,all=false){
  const result=[];
  for(const c of courses){if(cid&&c.id!==cid)continue;for(const m of c.modules){if(mid&&m.id!==mid)continue;(m.package?.flashcards||[]).forEach((card,index)=>{const review=c.reviews?.[`${m.id}:${index}`];if(all||!review||new Date(review.due)<=new Date())result.push({cid:c.id,mid:m.id,index,card,course:c.title,module:m.title});});}}
  return result;
}
export const empty=(title,text,ico='book',action='')=>`<div class="panel empty-state"><div class="empty-icon">${icon(ico)}</div><h2>${esc(title)}</h2><p>${esc(text)}</p>${action}</div>`;
const btn=(text,action,ico='arrow',primary=true)=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${icon(ico)}${text}</button>`;
export const courseStats = c => ({read:c.modules.filter(m=>m.read).length, ready:c.modules.filter(m=>m.package).length, mastered:c.modules.filter(m=>m.state==='mastered').length});

function heroArt(){return `<div class="hero-visual" aria-hidden="true"><svg viewBox="0 0 320 220"><ellipse class="orbit" cx="165" cy="107" rx="100" ry="83"/><ellipse class="orbit" cx="165" cy="107" rx="138" ry="54" transform="rotate(-28 165 107)"/><path class="twig" d="M89 188C116 141 162 104 224 37M142 126c-12-30-15-48-5-75m43 37c28 4 47 0 68-15M118 153c-29-11-44-25-54-48"/><path class="leaf" d="M142 112c-39-14-47-39-35-58 29 3 44 26 35 58Z"/><path class="leaf-dark" d="M159 106c4-37 25-56 48-53 1 31-16 50-48 53Z"/><path class="leaf" d="M180 91c28-19 53-17 66 2-19 23-44 21-66-2Z"/><path class="leaf" d="M117 151c-30 2-50-14-51-36 28-5 47 8 51 36Z"/><circle class="dot" cx="89" cy="188" r="4"/><circle class="dot" cx="137" cy="51" r="3"/><circle class="dot" cx="248" cy="73" r="3"/><circle class="dot" cx="224" cy="37" r="4"/><text class="note" x="172" y="194">ROOM TO GROW</text></svg></div>`;}
function courseArt(n){return `<div class="course-art" aria-hidden="true"><span class="art-label">A CONNECTED BODY OF KNOWLEDGE</span><span class="art-number">${String(n).padStart(2,'0')}</span><svg viewBox="0 0 300 160"><g fill="none" stroke="#a3b88e" stroke-width="1"><path d="M35 130C90 130 50 45 115 45S150 105 205 105 240 40 280 40"/><path d="M115 45c10 85 48 85 90 60M205 105c10 40 45 40 70 33"/><path stroke-dasharray="3 5" d="M15 100h285M15 60h285"/></g><g fill="#eaf0e1" stroke="#9fb28b"><circle cx="35" cy="130" r="13"/><circle cx="115" cy="45" r="19"/><circle cx="205" cy="105" r="24"/><circle cx="280" cy="40" r="13"/><circle cx="275" cy="138" r="9"/></g><g fill="#92aa7c"><circle cx="115" cy="45" r="4"/><circle cx="205" cy="105" r="5"/><circle cx="35" cy="130" r="3"/></g></svg></div>`;}

export function library(courses){
  const totalModules=courses.reduce((n,c)=>n+c.modules.length,0),read=courses.reduce((n,c)=>n+courseStats(c).read,0);
  return `<section class="library-hero"><div><div class="eyebrow">YOUR PERSONAL LEARNING SPACE</div><h1>Your learning,<br><em>connected.</em></h1><p>Turn a collection of course material into a clearer way to learn. One idea at a time.</p><div class="row mt-24"><a href="#/new" class="btn primary">${icon('plus')}Create a course</a><button class="btn ghost" data-action="import">${icon('download')}Import course</button></div></div>${heroArt()}</section>
  <div class="stats-strip"><div class="stat"><div class="stat-icon">${icon('book')}</div><div><strong>${courses.length}</strong><span>Courses in your space</span></div></div><div class="stat"><div class="stat-icon">${icon('graph')}</div><div><strong>${read}<small class="muted"> / ${totalModules}</small></strong><span>Modules studied</span></div></div><div class="stat"><div class="stat-icon">${icon('cards')}</div><div><strong>${dueCards(courses).length}</strong><span>Cards ready to review</span></div></div></div>
  <div class="section-heading"><h2>Your courses <small class="muted">&nbsp; ${courses.length.toString().padStart(2,'0')}</small></h2><small>A little progress, every day.</small></div><div class="course-grid">${courses.map((c,i)=>{
    const s=courseStats(c),percent=c.modules.length?Math.round(s.read/c.modules.length*100):0;
    return `<article class="panel course-card">${courseArt(i+1)}<div class="course-card-body"><div class="row between"><span class="eyebrow">${c.status==='ready'?'YOUR COURSE COMPANION':'IN PREPARATION'}</span>${c.demo?'<span class="pill outline">Sample course</span>':''}${deleteCourseButton(c,true)}</div><h3><a href="${courseLink(c)}">${esc(c.title)}</a></h3><p class="description">${esc(c.description||'Your materials are saved. Let’s give them a little structure.')}</p><div class="course-meta"><span>${icon('graph')}${c.modules.length} modules</span><span>${icon('file')}${c.documents.length} sources</span><span>${icon('shield')}Saved locally</span></div><div class="progress-line"><span style="width:${percent}%"></span></div></div><div class="course-card-bottom"><span>${c.status==='ready'?`${percent}% studied · ${s.mastered} strong recall`:c.job?.state==='running'?'Preparing your course…':'Ready for the next step'}</span><a href="${courseLink(c)}">${c.modules.some(m=>m.package)?(c.status==='ready'?'Open course':'Explore ready modules'):'Continue setup'}${icon('arrow')}</a></div></article>`;
  }).join('')}<a href="#/new" class="new-course-card"><div><div class="plus-circle">${icon('plus')}</div><h3>A new course.<br>A fresh perspective.</h3><p>Bring your PDFs. We’ll help you see how everything fits together.</p></div></a></div><div class="bottom-note">${icon('lock')}A space of your own. Your materials and progress stay on this computer.</div>`;
}

export function courseView(c,view='graph',zoom=1){
  const s=courseStats(c), ready=m=>m.package&&m.prerequisites.every(id=>c.modules.find(p=>p.id===id)?.read), next=c.modules.find(m=>m.package&&m.state==='weak')||c.modules.find(m=>ready(m)&&!m.read)||c.modules.find(m=>m.package&&!m.read)||c.modules.find(m=>m.package);
  const header=`<div class="page-head course-head"><div><div class="row"><span class="eyebrow">COURSE WORKSPACE</span>${c.demo?'<span class="pill outline">Sample course</span>':''}</div><h1>${esc(c.title)}</h1><p>${esc(c.description)}</p><div class="course-top-meta"><span>${icon('graph')}${c.modules.length} modules</span><span>${icon('file')}${c.documents.length} sources</span><span>${icon('check')}${s.read} studied</span><span>${icon('shield')}${c.status==='ready'?'Prepared & saved':`${c.modules.filter(m=>m.package).length} of ${c.modules.length} ready`}</span></div></div><div class="head-actions">${c.job?.state!=='running'?`<button class="btn" data-action="extend-course">${icon('plus')}Add module</button>`:''}${deleteCourseButton(c)}<a class="btn" href="/api/courses/${c.id}/export">${icon('download')}Export course</a>${next?`<a class="btn primary" href="${link(c.id,next.id)}">${icon('book')}${s.read?'Continue learning':'Start learning'}</a>`:''}</div></div><div class="course-tabs">${[['graph','graph','Knowledge map'],['outline','list','Course outline'],['materials','file','Sources & coverage']].map(([key,ico,text])=>`<button class="course-tab ${view===key?'active':''}" data-action="course-view" data-view="${key}">${icon(ico)}${text}</button>`).join('')}</div>`;
  if(view==='materials')return header+coverageSummary(c)+`<div class="section-heading"><h2>The source of your understanding</h2><small>${c.documents.length} original documents</small></div><div class="materials-grid">${c.documents.map(d=>`<article class="panel document-card"><div class="file-icon">${icon('file')}</div><div><span class="eyebrow">${d.role==='pyq'?'PAST PAPER':d.role==='syllabus'?'SYLLABUS':'LEARNING MATERIAL'}</span><h3>${esc(d.name)}</h3><p>${d.page_count} pages · ${d.readable_pages} with native text${d.visually_analyzed_pages?` · ${d.visually_analyzed_pages} visually analyzed`:""}</p>${d.text_warning_pages?`<p class="text-warning">${d.text_warning_pages} pages contain uncertain symbols. Check the original page for exact notation.</p>`:''}<button class="text-btn" data-action="source" data-doc="${d.id}" data-page="1">Open document ${icon('external')}</button></div></article>`).join('')}</div>${c.demo?'<p class="sample-note">'+icon('help')+'Original illustrative materials. The sample paper is not an actual university examination.</p>':''}`;
  if(view==='outline')return header+`<div class="outline-list">${c.modules.map((m,i)=>`<article class="panel outline-card"><span class="module-number">${String(i+1).padStart(2,'0')}</span><div class="spacer"><div class="row wrap"><h3>${esc(m.title)}</h3>${m.package?statePill(m):'<span class="pill amber">Preparing</span>'}</div><p>${esc(m.description)}</p><div class="topics">${m.topics.map(t=>`<span class="pill outline">${esc(t)}</span>`).join('')}</div></div><a class="btn sm" href="${m.package?link(c.id,m.id):link(c.id)+'/setup'}" aria-label="${m.package?'Study':'Preparing'} ${esc(m.title)}">${icon('arrow')}</a></article>`).join('')}</div>`;
  const depths={};function depth(m){return depths[m.id]??(depths[m.id]=m.prerequisites.length?1+Math.max(...m.prerequisites.map(id=>{const p=c.modules.find(x=>x.id===id);return p?depth(p):0;})):0);}
  c.modules.forEach(depth);const levels={};c.modules.forEach(m=>(levels[depths[m.id]]??=[]).push(m));
  const maxRows=Math.max(1,...Object.values(levels).map(x=>x.length)), height=Math.max(450,maxRows*155+85), cols=Object.keys(levels).length;
  const width=Math.max(760,cols*240+50),positions={};
  for(const [level,modules]of Object.entries(levels))modules.forEach((m,j)=>{positions[m.id]={x:30+Number(level)*240,y:(height-modules.length*155)/2+j*155+20};});
  const edges=c.modules.flatMap(m=>m.prerequisites.map(id=>{const p=positions[id],q=positions[m.id];if(!p)return '';return `<path class="graph-edge" marker-end="url(#arrowhead)" d="M${p.x+190} ${p.y+56} C${p.x+220} ${p.y+56},${q.x-30} ${q.y+56},${q.x-2} ${q.y+56}"/>`;})).join('');
  const map=`<div class="panel map-panel"><div class="map-toolbar"><div><strong>Your course, connected</strong><br><span>Follow a connection. Find your next idea.</span></div><div class="row" style="gap:5px"><button class="icon-btn" data-action="map-expand" aria-label="Expand map" aria-pressed="false">${icon('external')}</button><button class="icon-btn" data-action="zoom-out" aria-label="Zoom out">${icon('minus')}</button><button class="icon-btn" data-action="zoom-fit" aria-label="Fit entire map">${icon('fit')}</button><button class="icon-btn" data-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button></div></div><div class="graph-scroll" tabindex="0" role="region" aria-label="Course map; drag the background or use arrow keys to pan"><div style="width:${width*zoom}px;height:${height*zoom}px"><div class="graph-stage" data-width="${width}" data-height="${height}" style="width:${width}px;height:${height}px;transform:scale(${zoom})"><svg class="connections" aria-hidden="true"><defs><marker id="arrowhead" markerWidth="6" markerHeight="6" refX="4" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#bdcbb1"/></marker></defs>${edges}</svg>${c.modules.map((m,i)=>{const p=positions[m.id],count=c.pyqs.filter(q=>q.module_ids.includes(m.id)).length;return `<a class="graph-node ${esc(m.state)} ${m.package?'':'pending'}" title="${esc(m.title)}" style="left:${p.x}px;top:${p.y}px" href="${m.package?link(c.id,m.id):link(c.id)+'/setup'}"><div class="node-top">MODULE ${String(i+1).padStart(2,'0')}${count?`<span class="node-badge">${count} ${c.demo?'sample Q':'PYQ'}${count>1?'s':''}</span>`:''}</div><h3>${esc(m.title)}</h3><div class="node-bottom"><span class="status-dot ${esc(m.state)}"></span>${m.package?labelState(m.state):'Preparing'}<span class="spacer"></span>${m.topics.length} topics ${icon('chevron')}</div></a>`;}).join('')}</div></div></div><div class="map-legend">${['unseen','learning','weak','mastered'].map(s=>`<span><i class="status-dot ${s}"></i>${labelState(s)}</span>`).join('')}<span class="spacer"></span><span>Arrows suggest prerequisites</span></div></div>`;
  return header+`<div class="graph-layout"><div>${map}<p class="map-caption">Open a ready module to study. Unfinished modules show preparation progress.</p></div><aside class="course-aside"><div class="panel aside-card recommend"><span class="eyebrow">A GOOD PLACE TO ${s.read?'CONTINUE':'BEGIN'}</span><div class="aside-icon mt-16">${icon('leaf')}</div><h3>${esc(next?.title||'Take a moment to revise')}</h3><p>${esc(next?.description||'Return to a weaker module or review your saved cards.')}</p>${next?`<a class="text-btn" href="${link(c.id,next.id)}">Open study guide ${icon('arrow')}</a>`:''}</div><div class="panel aside-card"><span class="eyebrow">YOUR PROGRESS</span><div class="aside-stat mt-16"><span>Modules studied</span><strong>${s.read} / ${c.modules.length}</strong></div><div class="aside-stat"><span>Strong recall</span><strong>${s.mastered} modules</strong></div><div class="progress-line mt-16"><span style="width:${c.modules.length?s.read/c.modules.length*100:0}%"></span></div><p class="mt-16 small-text">Reading builds familiarity. Practice builds evidence of understanding.</p><a class="text-btn" href="#/revision">Review your flashcards ${icon('arrow')}</a></div></aside></div>${c.demo?'<p class="sample-note">'+icon('help')+'Explore a prepared sample. Create your own course whenever you’re ready.</p>':''}`;
}

export function studyHeader(c,m,tab){
  const number=c.modules.findIndex(x=>x.id===m.id)+1;
  return `<header class="study-header"><a class="back" href="${courseLink(c)}">${icon('back')}Back to knowledge map</a><div class="row"><span class="eyebrow">MODULE ${String(number).padStart(2,'0')}</span>${statePill(m)}${c.demo?'<span class="pill outline">Sample content</span>':''}</div><div class="study-title-row"><h1>${esc(m.title)}</h1><div class="row"><button class="btn" data-action="bookmark" aria-label="${m.bookmarked?'Remove bookmark':'Bookmark module'}">${icon('bookmark')}${m.bookmarked?'Saved':'Save'}</button><button class="btn ${m.read?'':'primary'}" data-action="mark-read">${icon('check')}${m.read?'Studied':'Mark as studied'}</button></div></div><p class="study-subtitle">${esc(m.description)}</p><nav class="study-tabs" aria-label="Module workspace">${[['study','book','Study guide'],['practice','target','Practice'],['pyqs','file','Past papers'],['cards','cards','Flashcards'],['notes','edit','My notes']].map(([key,ico,text])=>`<a class="study-tab ${tab===key?'active':''}" href="${link(c.id,m.id,key)}">${icon(ico)}${text}</a>`).join('')}</nav></header>`;
}
export function citations(refs,c){
  const unique=[...new Map((refs||[]).map(r=>[r.doc_id+':'+r.page,r])).values()];
  return `<div class="citations" aria-label="Source references"><span class="source-label">Sources</span>${unique.map((r,i)=>{const d=c.documents.find(d=>d.id===r.doc_id);return d?`<button class="citation compact" title="${esc(d.name)} · physical page ${Number(r.page)}" aria-label="Open ${esc(d.name)}, page ${Number(r.page)}" data-action="source" data-doc="${esc(r.doc_id)}" data-page="${Number(r.page)}">${icon('file')}[${i+1}] p. ${Number(r.page)}</button>`:'';}).join('')}</div>`;
}
function coverageSummary(c){
  const rows=c.documents.filter(d=>d.role!=='pyq');
  return `<section class="panel coverage-panel"><div class="section-heading"><div><span class="eyebrow">MATERIAL COVERAGE</span><h2>Keep every source in view.</h2></div><span class="pill outline">${rows.length} learning sources</span></div><p class="muted small-text">A module mapping records intended coverage. Citations show which pages were referenced; they do not prove every idea was explained.</p><div class="coverage-rows">${rows.map(d=>{
    const mapping=c.document_coverage?.find(r=>r.doc_id===d.id),modules=(mapping?.module_ids||[]).map(id=>c.modules.find(m=>m.id===id)).filter(Boolean);
    const cited=new Set(c.modules.flatMap(m=>(m.package?.sections||[]).flatMap(s=>(s.sources||[]).filter(r=>r.doc_id===d.id).map(r=>r.page))));
    return `<div class="coverage-row"><div><strong>${esc(d.name)}</strong><small>${c.scope_records?`${new Set(c.scope_records.filter(r=>r.doc_id===d.id).flatMap(r=>r.pages)).size} of ${d.page_count} pages have scope locations · ${cited.size} pages quoted`:`${cited.size} of ${d.page_count} pages cited`}${mapping?.supplied_pages?` · ${mapping.supplied_pages.length} pages sampled for outline`:''}</small></div><div>${modules.length?modules.map(m=>`<a class="pill outline" href="${link(c.id,m.id)}">${esc(m.title)}</a>`).join(' '):`<span class="pill amber">${mapping?'Needs coverage':'Mapping not reviewed'}</span>`}${mapping?.notes?`<p class="small-text muted">${esc(mapping.notes)}</p>`:''}</div></div>`;
  }).join('')}</div></section>`;
}
function diagramView(d){
  const layout=['flow','cycle','comparison'].includes(d.layout)?d.layout:'flow';
  return `<figure class="flow-panel ${layout}"><figcaption class="eyebrow">${esc(d.title)}</figcaption><div class="flow-nodes">${d.nodes.slice(0,8).map((n,j)=>`${j&&layout!=='comparison'?'<span class="flow-arrow" aria-hidden="true">→</span>':''}<div class="flow-node">${esc(n)}</div>`).join('')}${layout==='cycle'?'<span class="flow-arrow" aria-label="Repeats">↻</span>':''}</div></figure>`;
}

export function studyGuide(c,m){
  const p=m.package,minutes=Math.max(1,Math.round(p.sections.reduce((n,s)=>n+s.body.split(/\s+/).length,0)/180));
  const lessonStarts=p.sections.map((s,i)=>({s,i})).filter(({s,i})=>s.lesson_id&&(!i||p.sections[i-1].lesson_id!==s.lesson_id));
  const diagramSlots=new Map();
  for(const diagram of p.diagrams||[]){
    const indices=p.sections.map((s,i)=>({s,i})).filter(({s})=>!diagram.lesson_id||s.lesson_id===diagram.lesson_id);
    const at=indices[Math.min(2,indices.length-1)]?.i;
    if(at!==undefined){if(!diagramSlots.has(at))diagramSlots.set(at,[]);diagramSlots.get(at).push(diagram);}
  }
  return `<div class="study-layout"><aside class="lesson-toc"><span class="eyebrow">IN THIS MODULE</span><button class="toc-link" data-action="scroll-section" data-index="intro">Overview</button>${p.sections.map((s,i)=>`${s.lesson_id&&(!i||p.sections[i-1].lesson_id!==s.lesson_id)?`<span class="toc-group">${esc(s.lesson_title)}</span>`:''}<button class="toc-link" data-action="scroll-section" data-index="${i}">${esc(s.title)}</button>`).join('')}<div class="toc-bottom">${icon('clock')} About ${minutes} min<p>${m.topics.length} connected topics</p><p>${p.teaching_mode==='approved_scope'?'Topic locations available':'Sources linked throughout'}</p></div></aside><article class="panel lesson-paper"><div class="reader-mark-header"><p data-mark-help>Select text to highlight or underline.</p><div><button type="button" class="text-btn" data-mark-selection title="Select text, then use Alt+Shift+H to highlight or Alt+Shift+U to underline">Mark selection</button><button type="button" class="text-btn" data-marks-toggle aria-expanded="false">Your marks <span>0</span></button></div><small data-marks-status role="status" aria-live="polite"></small></div><section class="reader-marks" data-marks-panel hidden aria-label="Your text marks"><div data-marks-list></div></section><div id="section-intro"><span class="eyebrow">LET’S BUILD AN UNDERSTANDING</span><div class="lesson-intro mt-16" data-annotation-block="intro">${rich(p.overview)}</div></div>${p.teaching_mode==='approved_scope'?`<div class="notice mt-16">Generated teaching follows your reviewed scope. Topic locations show where a subject appears in your PDFs; they do not verify every explanation.</div><details class="topic-coverage"><summary>Topic locations in the original materials</summary>${(p.topic_locations||[]).map(r=>{const d=c.documents.find(d=>d.id===r.doc_id);return `<p><button class="text-btn" data-action="source" data-doc="${esc(r.doc_id)}" data-page="${r.start_page}">${esc(d?.name||'Source')} · physical pages ${r.start_page}–${r.end_page}</button></p>`;}).join('')}</details>`:''}${p.coverage_notes?`<details class="coverage-note"><summary>Source gaps & preparation notes</summary><div class="prose">${rich(p.coverage_notes)}</div></details>`:''}${p.corrections?.length?`<details class="correction-note"><summary>Reviewed source clarifications</summary>${p.corrections.map(note=>`<p>${esc(note.message)}</p>${/^https?:\/\//.test(note.url||'')?`<a class="text-btn" href="${esc(note.url)}" target="_blank" rel="noopener noreferrer">Read supporting reference ${icon('external')}</a>`:''}`).join('')}</details>`:''}<div class="learning-objectives"><span class="eyebrow">BY THE END, YOU’LL BE ABLE TO</span><ul>${p.objectives.map((o,i)=>`<li data-annotation-block="objective:${i}">${inline(o)}</li>`).join('')}</ul></div>${lessonStarts.length?`<nav class="lesson-index" aria-label="Focused lessons">${lessonStarts.map(({s,i},j)=>`<button data-action="scroll-section" data-index="${i}"><span>LESSON ${j+1}</span>${esc(s.lesson_title)}${icon('arrow')}</button>`).join('')}</nav>`:''}${p.coverage_map?.length?`<details class="topic-coverage"><summary>${p.coverage_map.length} topics in the teaching plan</summary>${p.coverage_map.map(t=>`<button class="toc-link" data-action="scroll-section" data-index="${Number(t.section)}">${esc(t.topic)} ${icon('arrow')}</button>`).join('')}</details>`:''}${p.sections.map((s,i)=>`<section class="lesson-section ${esc(s.kind)}" id="section-${i}">${s.lesson_id&&(!i||p.sections[i-1].lesson_id!==s.lesson_id)?`<div class="lesson-divider"><span class="eyebrow">FOCUSED LESSON</span><h2 data-annotation-block="lesson:${i}">${esc(s.lesson_title)}</h2></div>`:''}<div class="section-kicker">${s.kind==='example'?'WORKED EXAMPLE':s.kind==='pitfall'?'A COMMON MISUNDERSTANDING':s.kind==='recap'?'THE TAKEAWAY':String(i+1).padStart(2,'0')+' / '+(s.kind==='formula'?'KEY RELATIONSHIP':'UNDERSTAND THE IDEA')}</div><h2 data-annotation-block="heading:${i}">${esc(s.title)}</h2><div class="prose" data-annotation-block="section:${i}">${rich(s.body)}</div>${s.provenance?`<p class="small-text muted">${s.provenance==='generated'?'Generated teaching · explanations and examples have not been independently verified.':'Original source excerpt · quoted from the supplied text.'}</p>`:''}${s.sources?.length?citations(s.sources,c):''}</section>${(diagramSlots.get(i)||[]).map(diagramView).join('')}`).join('')}${m.prerequisites.length?`<p class="module-prereqs">Builds on ${m.prerequisites.map(id=>{const pre=c.modules.find(x=>x.id===id);return pre?`<a href="${link(c.id,pre.id)}">${esc(pre.title)}</a>`:'';}).filter(Boolean).join(', ')}.</p>`:''}<footer class="lesson-footer row between"><div><span class="eyebrow">READY TO PUT IT INTO PRACTICE?</span><br><small>Practice and revision cards can be prepared separately from your saved teaching.</small></div><a class="btn primary" href="${link(c.id,m.id,'practice')}">Practise this module ${icon('arrow')}</a></footer></article></div>`;
}

export function preparePractice(c,m,action='practice'){
  const job=c.job,own=job?.action===action&&(action!=='practice'||!job.module_id||job.module_id===m.id);
  const running=job?.state==='running',paused=own&&job?.state==='paused';
  const title=action==='papers'?'Prepare your uploaded questions.':'Your teaching is ready.';
  const description=action==='papers'?'Extract and map your uploaded past-paper questions in a separate preparation step.':'Generate practice questions and revision cards from the saved lessons when you want them. This uses Gemini; opening saved practice does not.';
  const label=paused||(action==='practice'&&m.practice_preparation)?'Resume preparation':action==='papers'?'Prepare past-paper questions':'Generate practice & cards';
  return `<section class="panel preparation-panel"><h2>${title}</h2><p>${description}</p>${own&&(running||paused)?`<p class="${paused?'coverage-note':'muted'}" role="status">${esc(job.message)}</p>`:''}${running&&!own?'<p class="muted">Another preparation step is running. Your saved lessons remain available.</p>':''}<button class="btn primary" data-action="${action==='papers'?'generate-papers':'generate-practice'}" ${running?'disabled':''}>${running&&own?'Preparing…':label}</button></section>`;
}

export function practice(c,m,quiz){
  if(m.package.assessment_status==='missing')return preparePractice(c,m);
  const bank=m.package.questions.filter(q=>q.type==='objective'),questions=(quiz.order||bank.map(q=>q.id)).map(id=>bank.find(q=>q.id===id)).filter(Boolean),subjective=m.package.questions.filter(q=>q.type==='subjective'&&(!quiz.topic||q.topic===quiz.topic)),r=quiz.result,e=m.evidence||{};
  const topics=[...new Set(bank.map(q=>q.topic).filter(Boolean))];
  return `<div class="practice-wrap"><div class="panel practice-evidence"><div><span class="eyebrow">EVIDENCE FROM YOUR SAVED BANK</span><h3>${e.unique||0} distinct question${e.unique===1?'':'s'} attempted</h3><p>${e.unique?`${Math.round(e.first_correct/e.unique*100)}% correct on first encounters`:'Your first encounters will appear here.'} · ${e.topics||0}/${e.total_topics||m.topics.length} topics practised.</p></div><small>Repeating questions builds recall. Strong recall needs at least 12 distinct questions and coverage across topics.</small></div><div class="practice-filter"><label for="practice-topic">Focus</label><select id="practice-topic" ${r?'disabled':''}><option value="">Whole module</option>${topics.map(t=>`<option value="${esc(t)}" ${quiz.topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select><span class="muted small-text">Question and option order vary each round.</span></div>${r?`<div class="panel score-panel"><span class="eyebrow">A MOMENT TO REFLECT</span><div class="score">${Math.round(r.correct/r.total*100)}<small>%</small></div><h2>${r.correct===r.total?'A strong practice round.':r.correct/r.total>=.5?'You’re making connections.':'A useful place to begin again.'}</h2><p>${r.correct} of ${r.total} correct · ${r.new_questions??0} first encounters. Review the explanations below.</p><button class="btn" data-action="reset-quiz">${icon('refresh')}Practise again</button></div>`:`<div class="panel practice-intro"><div><span class="eyebrow">RETRIEVE. REASON. REMEMBER.</span><h3>A little practice goes a long way.</h3><p>${questions.length} objective question${questions.length===1?'':'s'} · Answer at your own pace.</p></div><span class="pill outline">${c.demo?'Sample practice':'AI-generated practice'}</span></div>`}${questions.map((q,i)=>{const result=r?.results.find(x=>x.id===q.id),selected=quiz.answers?.[q.id],order=quiz.options?.[q.id]||q.options.map((_,j)=>j);return `<article class="panel question-card"><div class="question-head"><span class="eyebrow">QUESTION ${String(i+1).padStart(2,'0')} / ${questions.length}</span><span class="pill outline">${esc(q.topic||q.difficulty||'Core concept')}</span></div><div class="question-stem prose">${rich(q.question)}</div><div class="question-options" role="group" aria-label="Question ${i+1}">${order.map((canonical,j)=>`<label class="option ${selected===canonical?'selected':''} ${result?(canonical===result.correct_index?'correct':canonical===result.selected?'incorrect':''):''}"><input type="radio" name="${esc(q.id)}" value="${canonical}" data-question="${esc(q.id)}" aria-label="${String.fromCharCode(65+j)}: ${esc(q.options[canonical])}" ${selected===canonical?'checked':''} ${r?'disabled':''}><span class="option-letter">${String.fromCharCode(65+j)}</span><div class="option-content prose">${rich(q.options[canonical])}</div></label>`).join('')}</div>${result?`<div class="answer-explanation ${result.correct?'':'wrong'}"><strong>${result.correct?'That’s right.':'A chance to clarify.'}</strong><div class="prose">${rich(result.solution)}</div></div>`:''}</article>`;}).join('')}${!r?`<div class="practice-submit"><small id="answered-count">${Object.keys(quiz.answers||{}).length} of ${questions.length} answered</small><button class="btn primary" data-action="submit-quiz" ${Object.keys(quiz.answers||{}).length<questions.length?'disabled':''}>Check my answers ${icon('arrow')}</button></div>`:''}${subjective.length?`<div class="section-heading subjective-divider"><h2>Think it through</h2><small>Written practice · self-review</small></div>${subjective.filter(q=>!quiz.topic||q.topic===quiz.topic).map((q,i)=>`<article class="panel question-card"><span class="eyebrow">SUBJECTIVE QUESTION ${i+1}</span><div class="question-stem prose">${rich(q.question)}</div><button class="text-btn" data-action="reveal" data-target="subjective-${i}">Reveal solution ${icon('down')}</button><div id="subjective-${i}" class="solution-box hidden"><div class="eyebrow">${c.demo?'PREPARED SAMPLE SOLUTION':'AI-GENERATED SOLUTION'}</div><div class="prose">${rich(q.solution)}</div></div></article>`).join('')}`:''}<p class="pyq-note">Saved questions and answer keys. No AI calls are made while you practise. Generated answer keys have not been independently verified.</p></div>`;
}

export function paperCoverage(c){
  const papers=(c.documents||[]).filter(d=>d.role==='pyq'),coverage=c.pyq_coverage;
  const unreadable=coverage?.unreadable_pages??papers.reduce((n,d)=>n+d.page_count-(d.readable_pages??d.page_count),0);
  const issues=coverage?.issues||[],incomplete=unreadable>0||issues.length>0;
  if(!papers.length&&!coverage)return '';
  return `<aside class="${incomplete?'coverage-note':'notice'}" role="status"><strong>${incomplete?'Past-paper coverage needs review.':'Past-paper page coverage.'}</strong><p>${coverage?`${coverage.analyzed_pages} of ${coverage.total_pages} pages analyzed.`:'Readable native-text pages can be prepared separately.'} ${unreadable?`${unreadable} page(s) have no native text. Scanned-paper transcription is not available; review the original or upload a searchable PDF.`:''}</p><p>Only questions fully contained on readable pages are extracted. Questions spanning pages or embedded in images may be missing.</p>${issues.length?`<details><summary>Pages needing review (${issues.length})</summary>${issues.map(issue=>{const doc=papers.find(d=>d.id===issue.doc_id);return `<p><button class="text-btn" data-action="source" data-doc="${esc(issue.doc_id)}" data-page="${Number(issue.page)}">${esc(doc?.name||'Paper')} · physical page ${Number(issue.page)}</button><br>${esc(issue.reason)}</p>`;}).join('')}</details>`:''}</aside>`;
}

export function pastPapers(c,m){
  const questions=c.pyqs.filter(q=>q.module_ids.includes(m.id));
  const coverage=paperCoverage(c);
  const pending=c.documents?.some(d=>d.role==='pyq'&&(c.pyq_batches||[]).filter(id=>id.startsWith(d.id+':')).length<(d.readable_pages??d.page_count));
  if(!questions.length&&pending)return coverage+preparePractice(c,m,'papers');
  if(!questions.length)return coverage+empty('No saved past-paper questions here.','Review the page coverage above if you uploaded papers. Your generated practice is available separately.','file',`<a class="btn primary" href="${link(c.id,m.id,'practice')}">Open practice ${icon('arrow')}</a>`);
  return `${coverage}<div class="practice-wrap">${pending?preparePractice(c,m,'papers'):''}<div class="section-heading"><div><span class="eyebrow">FROM YOUR COURSE MATERIAL</span><h2 class="serif mt-16" style="font-size:29px">Questions worth returning to.</h2></div><span class="pill outline">${questions.length} mapped</span></div><p class="pyq-note">${c.demo?'These original sample questions demonstrate past-paper mapping. They are not from actual past examinations.':'Frequency reflects only your uploaded papers. It does not predict future exam questions.'}</p>${questions.map((q,i)=>`<article class="panel question-card"><div class="question-head"><span class="eyebrow">${esc(q.year||'UPLOADED PAPER')}${q.number?' · Q'+esc(q.number):''}</span>${q.marks?`<span class="pill outline">${esc(q.marks)} marks</span>`:''}</div><div class="question-stem prose">${rich(q.question)}</div><div class="source-controls"><button class="text-btn" data-action="reveal" data-target="pyq-${i}">Reveal solution ${icon('down')}</button>${citations([{doc_id:q.doc_id,page:q.page}],c)}</div><div id="pyq-${i}" class="solution-box hidden"><div class="eyebrow">${c.demo?'PREPARED SAMPLE SOLUTION':q.generated_solution?'AI-GENERATED SOLUTION · NOT AN OFFICIAL MARK SCHEME':'UPLOADED SOLUTION'}</div><div class="prose">${rich(q.solution)}</div></div></article>`).join('')}</div>`;
}

export function notes(m){return `<div class="practice-wrap"><div class="panel notes-panel"><div class="section-heading"><div><h2 class="serif" style="font-size:26px">Make the idea your own.</h2><small class="muted">Your questions, connections, and things to remember.</small></div>${icon('edit')}</div><div class="field"><label for="module-notes" class="hidden">Personal notes</label><textarea id="module-notes" maxlength="30000" placeholder="What clicked? What would you explain differently?">${esc(m.notes||'')}</textarea></div><div class="row between"><small class="muted" id="notes-status">Saved on this computer</small><button class="btn primary" data-action="save-notes">${icon('check')}Save notes</button></div></div></div>`;}

export function revision(courses){
  const due=dueCards(courses),total=courses.reduce((n,c)=>n+c.modules.reduce((n,m)=>n+(m.package?.flashcards.length||0),0),0);
  return `<div class="page-head"><div><span class="eyebrow">KEEP THE CONNECTIONS ALIVE</span><h1>A little recall.<br>A lasting understanding.</h1><p>Return to an idea just as it begins to fade. Your saved cards are ready whenever you are.</p></div>${due.length?`<div class="head-actions">${btn('Start daily review','start-review','cards')}</div>`:''}</div><div class="panel revision-summary"><span class="large">${due.length}</span><div><h3>${due.length?'ideas ready to revisit':total?'You’re all caught up.':'Prepare cards from saved lessons.'}</h3><p>${total} cards in your collection · Review intervals adapt to your ratings.</p></div></div><div class="section-heading"><h2>Review by course</h2><small>New cards count as ready to review</small></div><div class="stack">${courses.filter(c=>c.modules.some(m=>m.package)).map(c=>`<article class="panel revision-course-row"><span class="module-number">${icon('cards')}</span><div class="spacer"><h3>${esc(c.title)}</h3><p>${dueCards(courses,c.id).length} due · ${dueCards(courses,c.id,null,true).length} total cards</p></div><button class="btn sm" data-action="start-review" data-course="${c.id}">${icon('refresh')}Review course</button></article>`).join('')||empty('Your ideas will grow here.','Prepare a course, then generate its practice and revision cards separately.','cards')}</div>`;
}
export function flashcard(session){
  if(!session||session.pos>=session.cards.length)return empty('A little stronger than before.','No cards are due here. You can prepare missing cards from a module’s Practice tab.','check','<a class="btn primary" href="#/revision">Back to revision '+icon('arrow')+'</a>');
  const item=session.cards[session.pos];
  return `<div class="review-card-wrap"><div class="row between mb-16"><span class="eyebrow">${esc(item.module)}</span><span class="muted small-text">${session.pos+1} / ${session.cards.length}</span></div><div class="progress-line mb-16"><span style="width:${session.pos/session.cards.length*100}%"></span></div><button class="flashcard full" data-action="flip-card" aria-label="${session.flipped?'Card answer':'Reveal card answer'}"><span class="eyebrow">${session.flipped?'THE CONNECTION':'A MOMENT TO RECALL'}</span>${session.flipped?`<div class="card-answer prose">${rich(item.card.back)}</div>`:`<div class="card-front prose">${rich(item.card.front)}</div>`}<span class="flip-hint">${icon('refresh')}${session.flipped?'How well did you recall this?':'Think first. Click to reveal.'}</span></button>${session.flipped?`<div class="review-actions"><button class="btn" data-action="rate-card" data-rating="again">Again<small>in 10 minutes</small></button><button class="btn" data-action="rate-card" data-rating="good">Got it<small>grow the interval</small></button><button class="btn primary" data-action="rate-card" data-rating="easy">Easy<small>give it more time</small></button></div>`:'<p class="bottom-note">Recall the answer before turning the card.</p>'}</div>`;
}
export function saved(courses){const items=courses.flatMap(c=>c.modules.filter(m=>m.bookmarked).map(m=>({c,m})));return `<div class="page-head"><div><span class="eyebrow">YOUR PERSONAL REFERENCE SHELF</span><h1>Worth another look.</h1><p>A quiet place for the modules you want to keep close.</p></div></div>${items.length?`<div class="saved-list">${items.map(({c,m})=>`<article class="panel saved-item"><div class="aside-icon">${icon('bookmark')}</div><div class="spacer"><small>${esc(c.title)}</small><h3>${esc(m.title)}</h3>${m.package?statePill(m):'<span class="pill amber">Preparing</span>'}</div><a class="btn sm" href="${link(c.id,m.id)}">Open ${icon('arrow')}</a></article>`).join('')}</div>`:empty('Keep a good idea close.','Save a module from its study workspace and find it here whenever you need it.','bookmark','<a class="btn primary" href="#/">Explore your courses '+icon('arrow')+'</a>')}`;}

export function settingsView(settings,theme){
  const keyFields=[1,2,3].map(number=>{
    const slot=settings.key_slots?.find(s=>s.slot===number)||(number===1?settings:{}),suffix=number===1?'':`_${number}`;
    const sourceLabel=slot.key_source==='env_file'?'Connected from .env':slot.key_source==='environment'?'Connected from environment':slot.has_key?'Key saved':'Not connected';
    const hint=slot.has_key?'Leave blank to keep this key. Enter a new key to replace it.':`Paste a key here, or set GEMINI_API_KEY${suffix} in the .env file beside app.py.`;
    return `<div class="field"><label for="api-key${suffix}">Gemini API key ${number}${number>1?' (optional)':''} <span class="pill ${slot.has_key?'green':''}">${sourceLabel}</span></label><input id="api-key${suffix}" name="api_key${suffix}" type="password" autocomplete="off" placeholder="${slot.has_key?'Connected. Leave blank to keep it.':'Paste your Gemini API key'}"><small>${hint}</small>${slot.has_saved_key?`<button type="button" class="text-btn" data-action="clear-key" data-slot="${number}">Remove saved key ${number}</button>`:''}</div>`;
  }).join('');
  const count=settings.key_count??Number(settings.has_key),rotation=count>1?`Requests rotate across ${count} distinct configured keys in slot order.`:'Add up to three keys. Requests take turns across the distinct keys you configure.';
  return `<div class="page-head"><div><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1>A space that works for you.</h1><p>Connect your model, set the pace, and keep your workspace comfortable.</p></div></div><div class="settings-layout"><form id="settings-form" class="panel settings-panel"><h2>Your AI connection</h2><p class="muted">Used only when you explicitly prepare course content.</p>${keyFields}<p class="muted">${rotation} Duplicate entries are used once. Keys stay on your computer and are excluded from course exports. Keys in the same Google project share quotas.</p><div class="field"><label for="model">Learning content model</label><input id="model" name="model" value="${esc(settings.model)}" required pattern="gemini-[a-zA-Z0-9.\-]+"><small>Writes the teaching explanations and worked examples in each lesson.</small></div><div class="field"><label for="task-model">Other preparation tasks</label><input id="task-model" name="task_model" value="${esc(settings.task_model||'gemini-3.5-flash-lite')}" required pattern="gemini-[a-zA-Z0-9.\-]+"><small>Scope discovery, outlines, lesson plans, assessments, cards, and past papers.</small></div><div class="field"><label for="vision-model">Visual analysis model</label><input id="vision-model" name="vision_model" value="${esc(settings.vision_model||settings.task_model||'gemini-3.5-flash-lite')}" required pattern="gemini-[a-zA-Z0-9.\-]+"><small>Reads selected scans and diagrams. Use a model with PDF/image input. Saved results stay saved when models change; there is no automatic model fallback.</small></div><div class="field"><label for="interval">Time between preparation requests</label><select id="interval" name="interval">${[6,12,30,60].map(n=>`<option value="${n}" ${settings.interval===n?'selected':''}>${n} seconds${n===6?' · default':''}</option>`).join('')}</select><small>If a quota is reached, preparation pauses and saves its progress.</small></div>${tutorSettings(settings)}<button type="submit" class="btn primary">${icon('check')}Save connection</button><div class="settings-divider"></div><div class="setting-row"><div><strong>Appearance</strong><p>A comfortable place to spend a little time.</p></div><div class="theme-options"><button type="button" class="${theme==='light'?'active':''}" data-action="theme" data-theme="light">Light</button><button type="button" class="${theme==='dark'?'active':''}" data-action="theme" data-theme="dark">Dark</button></div></div><div class="settings-divider"></div><div class="setting-row"><div><strong>Bring a course with you</strong><p>Restore a saved Folium ZIP package.</p></div><button type="button" class="btn sm" data-action="import">${icon('download')}Import</button></div></form><aside class="panel settings-info">${icon('leaf')}<h3 class="mt-16">Prepare once.<br>Learn at your pace.</h3><p>Your study guides, diagrams, questions, and flashcards are saved with your course.</p><p>Reading, practising, reviewing cards, and keeping notes use no AI calls.</p><p>Saved course content works without a key. Scanned PDFs can use explicit visual scope analysis before outline preparation.</p></aside></div>`;
}

export function createView(){return `<div class="create-layout"><div class="page-head"><div><span class="eyebrow">A NEW CHAPTER</span><h1>Bring your course to life.</h1><p>Your PDFs are the starting point. We’ll turn them into a connected space for understanding.</p></div></div><div class="stepper"><span class="step active"><b>1</b>Bring materials</span><i class="step-line"></i><span class="step"><b>2</b>Shape your course</span><i class="step-line"></i><span class="step"><b>3</b>Prepare & learn</span></div><form id="create-form" class="panel upload-panel"><div class="field"><label for="course-title">What are you studying?</label><input id="course-title" name="title" required maxlength="120" placeholder="e.g. Engineering Mathematics II" autocomplete="off"></div><label class="dropzone" id="dropzone" tabindex="0" role="button"><input id="pdf-input" type="file" accept="application/pdf,.pdf" multiple hidden><span class="upload-icon">${icon('upload')}</span><h3>A little material. A lot of possibility.</h3><p>Drop your PDFs here, or <u>browse files</u></p><small>Syllabus, lecture notes, textbooks, and past papers · 25 MB per PDF</small></label><div id="upload-files" class="upload-files"></div><div class="notice mt-24">A syllabus is helpful, but optional. Label each document so your course can be structured around the right material. Readable and scanned PDFs are supported. Review visual page selection before recognition.</div><div id="create-error" class="field-error" role="alert"></div><div class="create-footer"><small>First, we’ll save your files locally. You’ll review the outline before generating any lessons.</small><button class="btn primary" type="submit">Save materials ${icon('arrow')}</button></div></form></div>`;}

export function uploadFileList(files){return files.map((f,i)=>`<div class="upload-file"><div class="file-icon">${icon('file')}</div><div class="file-name">${esc(f.file.name)}<small>${(f.file.size/1024/1024).toFixed(1)} MB</small></div><select data-file-role="${i}" aria-label="Document type for ${esc(f.file.name)}">${[['material','Learning material'],['syllabus','Syllabus'],['pyq','Past paper']].map(([value,label])=>`<option value="${value}" ${f.role===value?'selected':''}>${label}</option>`).join('')}</select><button class="icon-btn" type="button" data-action="remove-file" data-index="${i}" aria-label="Remove ${esc(f.file.name)}">${icon('close')}</button></div>`).join('');}

function visualPanel(c,settings){
  if(!c.visual)return !c.modules.length?`<section class="panel scope-review"><span class="eyebrow">BEFORE COURSE SCOPE</span><h2>Check scans and teaching visuals.</h2><p>Inspect all pages locally. Repeated logos and small margin images do not automatically enter recognition. Review the selected pages before sending them for visual analysis.</p><button class="btn" data-action="inspect-visual">Inspect visual pages · no AI calls</button></section>`:'';
  const v=c.visual,locked=!!c.scope_records||c.modules.length>0||c.job?.state==='running',selected=v.pages.filter(r=>r.selected),pending=selected.filter(r=>!r.result),shown=v.pages.filter(r=>r.state==='candidate'||r.selected);
  return `<section class="panel scope-review"><span class="eyebrow">VISUAL SCOPE ANALYSIS</span><h2>${selected.length} ${selected.length===1?'page':'pages'} selected across your PDFs</h2><p>${selected.length-pending.length} selected pages analyzed · ${v.pages.filter(r=>r.ignored_images).length} pages contain ignored margin images. Selection is a local heuristic; you can include a missed page manually. Originals stay unchanged.</p><p class="small-text muted">Selected pages are combined into analysis PDFs with saved mappings to their original physical pages. Model for remaining analysis: ${esc(settings.vision_model||settings.task_model||v.model||'gemini-3.5-flash-lite')}. Recognition may misread notation; it is not a verified transcription.</p><details data-scope-detail="visual-pages"><summary>Review visual page selection</summary>${shown.map(r=>{const d=c.documents.find(d=>d.id===r.doc_id);return `<div class="visual-page-row"><label class="scope-choice"><input type="checkbox" data-visual-doc="${esc(r.doc_id)}" data-visual-page="${r.page}" ${r.selected?'checked':''} ${locked?'disabled':''}><span><strong>${esc(d?.name||'Source')} · physical page ${r.page}</strong><small>${esc(r.reason)}</small><small>${r.result?`Saved result: ${esc(r.result)}`:'Not analyzed'}</small></span></label><button class="text-btn" data-action="source" data-doc="${esc(r.doc_id)}" data-page="${r.page}">View original page</button></div>`;}).join('')||'<p>No visual candidates selected. Native text remains available.</p>'}</details>${!locked?`<div class="scope-range"><label for="visual-manual-doc">Include another page</label><select id="visual-manual-doc">${c.documents.filter(d=>d.role!=='pyq').map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('')}</select><input id="visual-manual-page" type="number" min="1" value="1" aria-label="Physical PDF page to include"><button class="btn sm" data-action="include-visual-page">Include page</button></div><div class="row wrap"><button class="btn" data-action="inspect-visual">Re-inspect pages · no AI calls</button><button class="btn" data-action="save-visual">Save selection</button><button class="btn primary" data-action="analyze-visual" ${!selected.length?'disabled':''}>Analyze selected visual pages</button><button class="text-btn" data-action="skip-visual">Use native text only</button></div><p class="small-text muted">Analysis sends selected page images and bounded surrounding text to Gemini. Re-inspection refreshes suggestions while keeping saved choices and completed analysis. Successful batches are saved and reused. Skipped teaching visuals remain a visible scope gap.</p>`:''}${v.batch_ids?.length?`<details><summary>Saved combined analysis PDFs</summary>${v.batch_ids.map((id,i)=>`<p><a class="text-btn" href="/api/courses/${esc(c.id)}/visual/batches/${esc(id)}.pdf" target="_blank" rel="noopener">Open combined batch ${i+1}</a></p>`).join('')}</details>`:''}</section>`;
}

function scopeFields(c,m){
  if(!c.scope_records)return '';
  return `<div class="field"><label>Scope records for this module</label><details class="scope-picker" data-scope-detail="${esc(m.id)}"><summary>${(m.scope_ids||[]).length} selected · review topics and depth</summary>${c.scope_records.map(r=>`<label class="scope-choice"><input type="checkbox" data-draft-scope="${esc(m.id)}" value="${esc(r.id)}" ${(m.scope_ids||[]).includes(r.id)?'checked':''}><span><strong>${esc(r.title)}</strong><small>${esc(r.depth)}</small><small>${esc(r.subtopics.join(' · '))}</small><small>${esc(c.documents.find(d=>d.id===r.doc_id)?.name||'Source')} · physical pages ${r.pages.join(', ')}</small></span></label>`).join('')}</details></div><div class="field"><label>Approved source ranges · physical PDF pages</label><div data-ranges="${esc(m.id)}">${(m.source_ranges||[]).map((r,i)=>`<div class="scope-range"><select data-range-doc="${esc(m.id)}" data-index="${i}" aria-label="Source document for range ${i+1}">${c.documents.filter(d=>d.role!=='pyq').map(d=>`<option value="${esc(d.id)}" ${d.id===r.doc_id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><label>From <input type="number" min="1" value="${Number(r.start_page)}" data-range-start="${esc(m.id)}" data-index="${i}" aria-label="First PDF page of range ${i+1}"></label><label>To <input type="number" min="1" value="${Number(r.end_page)}" data-range-end="${esc(m.id)}" data-index="${i}" aria-label="Last PDF page of range ${i+1}"></label><button class="icon-btn" data-action="remove-range" data-module="${esc(m.id)}" data-index="${i}" aria-label="Remove source range ${i+1}">${icon('close')}</button></div>`).join('')}</div><button class="text-btn" data-action="add-range" data-module="${esc(m.id)}">${icon('plus')}Add source range</button><small class="muted">Selected scope records supply their original pages. Add ranges explicitly for supplementary material.</small></div><div class="field"><label for="scope-notes-${esc(m.id)}">Reviewed scope, depth, and convention clarifications</label><textarea id="scope-notes-${esc(m.id)}" data-draft-scope-notes="${esc(m.id)}" maxlength="12000" placeholder="Clarify the expected depth, notation, or boundaries…">${esc(m.scope_notes||'')}</textarea></div>`;
}

function scopeReview(c,draft,exclusions,acknowledged){
  if(!c.scope_coverage)return '';
  const s=c.scope_coverage,editable=c.modules.length&&!c.modules.some(m=>m.package||m.preparation)&&c.job?.state!=='running';
  const mapped=new Set(draft.flatMap(m=>m.scope_ids||[]));
  return `<section class="panel scope-review"><span class="eyebrow">SAVED COURSE SCOPE</span><h2>${s.processed_pages} of ${s.total_pages} pages processed</h2><p class="muted">${s.records} scope records · ${s.unresolved.length} page${s.unresolved.length===1?'':'s'} need${s.unresolved.length===1?'s':''} attention. Processed text does not mean every concept or visual element was recognized correctly. Recognized text and visual interpretations can contain errors; check important notation against the originals.</p>${s.non_teaching?.length?`<details data-scope-detail="non-teaching"><summary>Pages or segments excluded as non-teaching material</summary>${s.non_teaching.map(r=>`<p>${esc(c.documents.find(d=>d.id===r.doc_id)?.name||'Source')} · p. ${r.page}: ${esc(r.reason)}</p>`).join('')}</details>`:''}${s.unresolved.length?`<details class="coverage-note" data-scope-detail="unresolved"><summary>Review unresolved pages</summary>${s.unresolved.map(r=>{const d=c.documents.find(d=>d.id===r.doc_id);return `<p><button class="text-btn" data-action="source" data-doc="${esc(r.doc_id)}" data-page="${r.page}">${esc(d?.name||'Source')} · p. ${r.page}</button><br>${esc(r.reason)}</p>`;}).join('')}</details>`:''}<details data-scope-detail="records"><summary>Review scope records, conventions, and exclusions</summary>${c.scope_records.map(r=>{const d=c.documents.find(d=>d.id===r.doc_id),excluded=exclusions.find(x=>x.scope_id===r.id);return `<article class="scope-record"><h3>${esc(r.title)}</h3>${r.origin==='visual_interpretation'?'<span class="pill amber">Visual scope · unverified interpretation</span>':''}${r.visual_warning?`<p class="coverage-note">${esc(r.visual_warning)}</p>`:''}<p>${esc(r.depth)}</p><p class="small-text">${esc(r.subtopics.join(' · '))}</p>${r.methods.length?`<p><strong>Methods:</strong> ${esc(r.methods.join(' · '))}</p>`:''}${r.conventions.length?`<p><strong>Conventions:</strong> ${esc(r.conventions.join(' · '))}</p>`:''}${r.uncertainties.length?`<p class="coverage-note">${esc(r.uncertainties.join(' · '))}</p>`:''}${r.anchor_warnings?.length?`<p class="coverage-note">${esc(r.anchor_warnings.map(w=>w.reason).join(' · '))}</p>`:''}<p class="small-text muted">${esc(d?.name||'Source')} · physical pages ${r.pages.join(', ')}</p>${mapped.has(r.id)?'<span class="pill green">Assigned to a module</span>':`<span class="pill amber">${excluded?'Excluded with reason':'Unassigned'}</span>`}${editable?`<div class="field"><label for="exclude-${esc(r.id)}">Exclusion reason · leave empty when assigned</label><input id="exclude-${esc(r.id)}" data-scope-exclusion="${esc(r.id)}" value="${esc(excluded?.reason||'')}" maxlength="1200"></div>`:''}</article>`;}).join('')}</details>${editable&&s.unresolved.length?`<label class="scope-ack"><input type="checkbox" id="acknowledge-scope-gaps" ${acknowledged?'checked':''}>I reviewed the unresolved pages and accept the visible scope gaps.</label>`:''}</section>`;
}

export function setupView(c,draft,settings,exclusions=c.scope_exclusions||[],acknowledged=!!c.scope_review){
  const job=c.job,running=job?.state==='running',paused=job?.state==='paused',hasPackages=c.modules.some(m=>m.package);
  let body='';
  if(running||paused||hasPackages||c.modules.some(m=>m.preparation)){
    const done=c.modules.filter(m=>m.package).length;
    body=`<div class="panel job-panel"><div class="row between"><h2 class="serif" style="font-size:27px">${paused?'Your progress is safe.':'A course, coming together.'}</h2>${running?'<div class="spinner"></div>':icon('shield')}</div><p class="job-message">${esc(job?.message||'Continue preparing the remaining material.')}</p><div class="progress-line"><span style="width:${job?.total?Math.round((job.done||0)/job.total*100):c.modules.length?Math.round(done/c.modules.length*100):8}%"></span></div>${[['Read your documents',`${c.documents.length} sources saved on this computer`,true],['Structure the course',c.modules.length?`${c.modules.length} modules mapped`:'Finding the connections',!!c.modules.length],['Prepare detailed lessons',`${done} of ${c.modules.length||'—'} modules saved`,done===c.modules.length&&done>0],['Ready to study','Practice and cards can be prepared later',c.status==='ready']].map(([title,text,complete],i)=>`<div class="job-stage ${!complete?'active':''}"><div class="stage-circle">${complete?icon('check'):i+1}</div><div><h3>${title}</h3><p>${text}</p></div></div>`).join('')}${paused||(!running&&done<c.modules.length)?`<div class="row wrap"><button class="btn primary" data-action="resume">${icon('refresh')}${job?'Resume preparation':'Prepare missing content'}</button><a class="btn" href="#/settings">Check connection</a></div>`:'<p class="small-text muted">You can leave this page. Each completed step is saved. Keep the local server running to continue preparation.</p>'}${done?`<div class="row wrap mt-16"><button class="btn primary" data-action="open-prepared">${icon('book')}Explore ready modules</button>${running?'<span class="small-text muted">Preparation continues while you read.</span>':''}</div>`:''}</div>`;
  }else if(!c.modules.length){
    body=`<div class="panel job-panel"><span class="eyebrow">YOUR MATERIALS ARE HERE</span><h2 class="serif mt-16" style="font-size:29px">Let’s find the connections.</h2><p class="job-message">We’ll process all readable learning text into saved scope records, then organize an outline. Review the scope and page ranges before preparing lessons. Large courses may need several resumable scope requests.</p><ul class="checklist">${c.documents.map(d=>`<li>${esc(d.name)} · ${d.page_count} pages</li>`).join('')}</ul>${!settings.has_key?'<div class="coverage-note">Add your Gemini key in Settings to prepare the outline. Your PDFs are already saved.</div>':''}<div class="row wrap"><button class="btn primary" data-action="prepare-outline">${icon('spark')}Prepare outline</button>${!settings.has_key?'<a class="btn" href="#/settings">Connect Gemini</a>':''}</div></div>`;
  }else{
    body=`<div class="notice mb-16">Make this outline yours. Rename modules, edit topic lists, and adjust prerequisites before generating. Review the saved scope, exclusions, depth, and source ranges. The outline locks when lesson preparation starts.</div><div id="outline-editors">${draft.map((m,i)=>`<article class="panel outline-editor" data-module="${esc(m.id)}"><div class="row mb-16"><span class="editor-num">${String(i+1).padStart(2,'0')}</span><span class="eyebrow">MODULE</span><span class="spacer"></span><button class="icon-btn" data-action="remove-module" data-index="${i}" aria-label="Remove module ${i+1}">${icon('close')}</button></div><div class="field"><label for="title-${esc(m.id)}">Module title</label><input id="title-${esc(m.id)}" data-draft-title="${esc(m.id)}" value="${esc(m.title)}" maxlength="150"></div><div class="field"><label for="topics-${esc(m.id)}">Topics · one per line</label><textarea id="topics-${esc(m.id)}" data-draft-topics="${esc(m.id)}">${esc(m.topics.join('\n'))}</textarea></div>${scopeFields(c,m)}<div class="field"><label>Suggested prerequisites</label><div class="prereq-select">${draft.filter(x=>x.id!==m.id).map(p=>`<label><input type="checkbox" data-draft-parent="${esc(m.id)}" value="${esc(p.id)}" ${m.prerequisites.includes(p.id)?'checked':''}>${esc(p.title)}</label>`).join('')||'<span class="muted">No other modules yet.</span>'}</div></div></article>`).join('')}</div><button class="btn full" data-action="add-module">${icon('plus')}Add module</button><div class="create-footer"><button class="btn" data-action="save-outline">${icon('check')}Save outline</button><button class="btn primary" data-action="generate-course">${icon('spark')}Generate & save lessons</button></div><p class="bottom-note">Preparation uses one teaching-plan request per new module, then one request per focused lesson (1–8 lessons). Practice and cards are generated separately from saved lessons. Completed stages are reused after pauses.</p>`;
  }
  return `<div class="create-layout"><div class="page-head"><div><span class="eyebrow">YOUR COURSE, TAKING SHAPE</span><h1>${esc(c.title)}</h1><p>${running?'A thoughtful learning space takes a little preparation.':paused?'Everything completed so far is saved on this computer.':'A clear structure makes room for better understanding.'}</p></div>${deleteCourseButton(c)}</div><div class="stepper"><span class="step active"><b>✓</b>Bring materials</span><i class="step-line"></i><span class="step ${c.modules.length?'active':''}"><b>2</b>Shape your course</span><i class="step-line"></i><span class="step ${hasPackages?'active':''}"><b>3</b>Prepare & learn</span></div>${c.warnings.map(w=>`<div class="coverage-note">${esc(w)}</div>`).join('')}${c.modules.length&&c.status!=='ready'?'<p class="notice mb-16">Only unfinished content is prepared: one teaching-plan request per new module, then one request per lesson (1–8 lessons). Practice, cards, and uploaded questions are separate preparation steps. Saved lessons are reused.</p>':''}${visualPanel(c,settings)}${scopeReview(c,draft,exclusions,acknowledged)}${body}</div>`;
}
